create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(),organization_code text unique not null,organization_name text not null,district_name text not null,province_name text not null,activation_code_hash text unique not null,license_status text not null default 'active' check(license_status in ('active','suspended','expired')),license_start_date date not null,license_end_date date not null,max_devices int not null default 10,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.activated_devices(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,device_id text not null,device_name text,user_name text,browser_info text,activation_date timestamptz default now(),last_check timestamptz default now(),status text default 'active' check(status in ('active','disabled')),created_at timestamptz default now(),unique(organization_id,device_id));
alter table public.organizations enable row level security;alter table public.activated_devices enable row level security;
-- Kode plaintext tidak disimpan. Buat hash server-side: crypt(upper(trim(kode)), gen_salt('bf')).
create or replace function public.activate_device(p_code text,p_device_id text,p_device_name text,p_user_name text,p_browser_info text) returns json language plpgsql security definer set search_path=public as $$ declare o organizations; d activated_devices; begin select * into o from organizations where activation_code_hash=crypt(upper(trim(p_code)),activation_code_hash) limit 1;if o.id is null then raise exception 'Kode aktivasi tidak valid';end if;if o.license_status<>'active' or current_date not between o.license_start_date and o.license_end_date then raise exception 'Lisensi tidak aktif';end if;if (select count(*) from activated_devices where organization_id=o.id and status='active')>=o.max_devices and not exists(select 1 from activated_devices where organization_id=o.id and device_id=p_device_id) then raise exception 'Batas perangkat tercapai';end if;insert into activated_devices(organization_id,device_id,device_name,user_name,browser_info) values(o.id,p_device_id,p_device_name,p_user_name,p_browser_info) on conflict(organization_id,device_id) do update set last_check=now(),status='active',device_name=excluded.device_name,user_name=excluded.user_name returning * into d;return json_build_object('organizationId',o.id,'organizationName',o.organization_name,'district',o.district_name,'province',o.province_name,'licenseStatus',o.license_status,'licenseEndDate',o.license_end_date,'deviceId',d.id);end $$;
revoke all on function public.activate_device(text,text,text,text,text) from public;grant execute on function public.activate_device(text,text,text,text,text) to anon,authenticated;
